const orders = $input.all().map(item => item.json);
const PAID_STATUSES = ['processing', 'completed'];

function extractMeta(metaArr, key) {
  const found = (metaArr || []).find(m => m.key === key);
  return found ? found.value : '';
}

function decodeEntities(str) {
  if (!str) return str;
  return str.replace(/&#038;/g, '&').replace(/&amp;/g, '&');
}

function parsePickupDateTime(isoDate, timeStr) {
  if (!isoDate) return null;
  const timeMatch = (timeStr || '').match(/(\d{1,2}):(\d{2})\s*(AM|PM)/i);
  let hour = 9, minute = 0;
  if (timeMatch) {
    hour = parseInt(timeMatch[1], 10);
    minute = parseInt(timeMatch[2], 10);
    const ampm = timeMatch[3].toUpperCase();
    if (ampm === 'PM' && hour !== 12) hour += 12;
    if (ampm === 'AM' && hour === 12) hour = 0;
  }
  const pad = n => String(n).padStart(2, '0');
  return `${isoDate}T${pad(hour)}:${pad(minute)}:00`;
}

const results = [];

for (const order of orders) {
  if (!PAID_STATUSES.includes(order.status)) continue;

  const customerName = `${order.billing?.first_name || ''} ${order.billing?.last_name || ''}`.trim();
  const customerEmail = order.billing?.email || '';
  const customerPhone = order.billing?.phone || '';

  const balanceFee = (order.fee_lines || []).find(f => (f.name || '').toLowerCase().includes('balance'));
  const balanceDue = balanceFee ? Math.abs(parseFloat(balanceFee.total || '0')) : 0;
  const paidNow = parseFloat(order.total || '0');
  const overallPrice = (paidNow + balanceDue).toFixed(2);
  const currencySymbol = order.currency_symbol || '$';
  const multiTour = (order.line_items || []).length > 1;

  for (const li of (order.line_items || [])) {
    const meta = li.meta_data || [];
    const tourName = decodeEntities(extractMeta(meta, 'Tour')) || decodeEntities(extractMeta(meta, 'Vehicle')) || li.name;
    const tourType = decodeEntities(extractMeta(meta, 'product_name_n'));
    const isoDate = extractMeta(meta, 'Date');
    const pickupTime = extractMeta(meta, 'Pickup Time');
    const from = decodeEntities(extractMeta(meta, 'From'));
    const to = decodeEntities(extractMeta(meta, 'To'));
    const passengers = extractMeta(meta, 'Passengers');
    const vehicle = extractMeta(meta, 'Vehicle');
    const durationMeta = extractMeta(meta, 'Duration') || extractMeta(meta, 'duration_name_n');

    const startDateTime = parsePickupDateTime(isoDate, pickupTime);
    if (!startDateTime) continue;

    let durationHours = 2;
    const durMatch = (durationMeta || '').match(/(\d+)\s*hours?/i);
    if (durMatch) durationHours = parseInt(durMatch[1], 10);

    const start = new Date(startDateTime);
    const end = new Date(start.getTime() + durationHours * 60 * 60 * 1000);
    const pad = n => String(n).padStart(2, '0');
    const endDateTime = `${end.getFullYear()}-${pad(end.getMonth()+1)}-${pad(end.getDate())}T${pad(end.getHours())}:${pad(end.getMinutes())}:00`;

    const eventId = `crtt${order.id}o${li.id}`;

    const descLines = [
      `Order #${order.number} (ID ${order.id})`,
      tourType ? `Type: ${tourType}` : null,
      `Customer: ${customerName}`,
      customerEmail ? `Email: ${customerEmail}` : null,
      customerPhone ? `Phone: ${customerPhone}` : null,
      passengers ? `Passengers: ${passengers}` : null,
      from ? `From: ${from}` : null,
      to ? `To: ${to}` : null,
      vehicle ? `Vehicle: ${vehicle}` : null,
      '',
      multiTour ? '--- Order Pricing (shared across all tours in this order) ---' : '--- Pricing ---',
      `Overall Trip Cost: ${currencySymbol}${overallPrice}`,
      `Paid via ${order.payment_method_title || order.payment_method}: ${currencySymbol}${paidNow.toFixed(2)}`,
      balanceDue > 0 ? `Balance Due on Arrival (Cash): ${currencySymbol}${balanceDue.toFixed(2)}` : `Balance Due: ${currencySymbol}0.00 (fully paid)`
    ].filter(line => line !== null);

    results.push({
      json: {
        eventId,
        summary: `${tourName} - ${customerName}`,
        description: descLines.join('\n'),
        startDateTime,
        endDateTime
      }
    });
  }
}

return results;

